local questDB=pfDB["quests"]["data"]
local knownQuests={}
for id,data in pairs(cmangosQuests) do
  knownQuests[id]=true
  local previous=questDB[id] or {}
  if previous["event"] then data["event"]=previous["event"] end
  if previous["obj"] then
    data["obj"]=data["obj"] or {}
    if previous["obj"]["IR"] then data["obj"]["IR"]=previous["obj"]["IR"] end
    if previous["obj"]["Z"] then data["obj"]["Z"]=previous["obj"]["Z"] end
  end
  questDB[id]=data
end

-- Do not advertise VMaNGOS-only quests that do not exist in Classic-DB.
for id in pairs(questDB) do
  if not knownQuests[id] then questDB[id]=nil end
end

cmangosQuests=nil
knownQuests=nil
